{
  "assessment": "Tajikistan enters my tenure in a remarkably stable position: the economy is growing rapidly at 8.4%, all domestic demographics and factions are supportive, and state finances are manageable with a moderate deficit of 2.5%. Security forces are currently loyal, and our regional relations within the SCO and CSTO are secure. My immediate priority is to consolidate this positive momentum by maintaining strict social order while boosting infrastructure and public welfare to cement long-term stability and economic resilience, ensuring no vulnerabilities emerge from our powerful neighbours.",
  "directives": [
    {
      "type": "set_tax",
      "target": null,
      "amount": 20.0,
      "sub": "",
      "order": "Set government tax revenue to 20 percent of GDP to maintain solid fiscal footing."
    },
    {
      "type": "set_spending",
      "target": null,
      "amount": 5.0,
      "sub": "health",
      "order": "Increase health spending to 5 percent of GDP."
    },
    {
      "type": "set_spending",
      "target": null,
      "amount": 6.0,
      "sub": "education",
      "order": "Increase education spending to 6 percent of GDP."
    },
    {
      "type": "invest_infrastructure",
      "target": null,
      "amount": 1.0,
      "sub": "",
      "order": "Invest an extra 1 percent of GDP into infrastructure development."
    },
    {
      "type": "monetary_policy",
      "target": null,
      "amount": -0.5,
      "sub": "",
      "order": "Lower policy rate by 0.5 percentage points to stimulate continued private sector growth."
    }
  ],
  "cables": [
    {
      "to": "RUS",
      "private": true,
      "text": "Greetings from Dushanbe. We reaffirm our commitment to our strong strategic partnership within the CSTO and SCO, and look forward to deepening our economic and security cooperation."
    },
    {
      "to": "CHN",
      "private": true,
      "text": "Greetings. As our primary trade partner, Tajikistan values its stable and cooperative relationship with China and seeks to expand mutual trade and investment initiatives."
    }
  ],
  "public_statement": "The Government of Tajikistan is committed to maintaining national stability, fostering robust economic growth, and improving the livelihoods of all our citizens through targeted investments in healthcare, education, and infrastructure.",
  "standing_orders": [
    {
      "when": "unrest_at_least:protests",
      "do": {
        "type": "repression_level",
        "target": null,
        "amount": 0.8,
        "sub": "",
        "order": "Maintain firm control over public order if protests emerge."
      }
    }
  ],
  "detailed_report": "economy"
}
